// Kronos Bot — Fase 4: arbol de decision para instrucciones de seguimiento
// sobre señales ya confirmadas/abiertas. Fuente de reglas: PROTOCOLOS_KRONOS_BOT.md
// secciones 3.2, 4.2 regla 7, 8.4, y el diseño de la tarea Fase 4.
//
// Entrada: este nodo corre despues de "Buscar señal referenciada" (Postgres),
// que devuelve SIEMPRE 1 fila con matched_signals (json_agg) y prior_sl_to_be
// (json_agg) para el message_id al que responde este mensaje (o null/[] si no
// hay match). Los campos originales del webhook (text, reply_to_message_id,
// message_id, chat_id...) se leen del nodo IF previo, no de este item.

const original = $('Recibido de otro workflow').item.json;
const row = $json;
const matched = row.matched_signals || [];
const priorSlToBe = row.prior_sl_to_be || [];

const rawText = (original.text || '').trim().replace(/\s+/g, ' ');

function skip(reason) {
  return [{
    json: {
      outcome: 'SKIP',
      skip_reason: reason,
      raw_text: rawText,
      message_id: original.message_id,
    },
  }];
}

// 1. PRE-FILTRO GRATIS: sin reply válido, o el reply no corresponde a
// ninguna fila existente en `signals` -> NO_RELACIONADO. No se guarda nada.
if (!original.reply_to_message_id || matched.length === 0) {
  return skip('NO_RELACIONADO');
}

// 2. FILTRO DE LONGITUD: mensajes largos son comentario/analisis, no
// instrucciones reales de este caller. No llega a regex ni a Gemini.
if (rawText.length > 200) {
  return skip('COMENTARIO_LARGO');
}

// 3. REGEX, en orden exacto -------------------------------------------------

// a) Informativo/no-op: TPx +N PIPS, o "BE" suelto (BE informativo, NUNCA
//    se interpreta como refuerzo del comando "mover SL a BE" — protocolo
//    seccion 4.2 regla 7).
if (/^TP\d?,?\s*\+?\d+\s*PIPS/i.test(rawText)) {
  return skip('INFORMATIVO_TP_PIPS');
}
if (/^BE$/i.test(rawText)) {
  return skip('INFORMATIVO_BE_SUELTO');
}

// b) Ignorar sin registro: TP3/TP4+ — el sistema solo trackea A=TP1, B=TP2
//    (protocolo seccion 13, tope de sub-señales trackeadas por este flujo).
if (/\bTP\s*[3-9]\b/i.test(rawText)) {
  return skip('TP_NO_TRACKEADO');
}

let modification_type = null;
let target_price = null;

// c) CANCEL
if (/ELIMINAR\s+ESTA\s+OPERACI[OÓ]N/i.test(rawText)) {
  modification_type = 'CANCEL';
}

// d) CLOSE_ALL_TO_BE — aplica a TODAS las sub-señales OPEN del message_id
//    referenciado (ya agrupadas por la query de "Buscar señal referenciada",
//    mismo criterio que _related_tickets() en dashboard/main.py).
if (!modification_type && /CERRAR\s+(ESTA\s+OPERACI[OÓ]N\s+)?A\s+BE(\s+ESTA\s+OPERACI[OÓ]N)?/i.test(rawText)) {
  modification_type = 'CLOSE_ALL_TO_BE';
}

// e) CLOSE_AT_PRICE
if (!modification_type) {
  const m = rawText.match(/CERRAR\s+(AHORA\s+)?A\s+(\d+(?:\.\d+)?)/i);
  if (m) {
    modification_type = 'CLOSE_AT_PRICE';
    target_price = parseFloat(m[2]);
  }
}

// f) TP_UPDATE
if (!modification_type) {
  const m = rawText.match(/MOVER\s+(EL\s+)?TP\s+A\s+(\d+(?:\.\d+)?)/i);
  if (m) {
    modification_type = 'TP_UPDATE';
    target_price = parseFloat(m[2]);
  }
}

// g) SL_TO_BE — con guard de idempotencia (no reprocesar refuerzo duplicado).
if (!modification_type && /MOVER\s+(EL\s+)?SL\s+A\s+BE/i.test(rawText)) {
  modification_type = 'SL_TO_BE';
}

// Si no matcheo ningun regex -> Gemini (unico punto con costo de tokens).
if (!modification_type) {
  const ref = matched[0];
  return [{
    json: {
      outcome: 'GEMINI',
      raw_text: rawText,
      message_id: original.message_id,
      instrument: ref.instrument,
      direction: ref.direction,
      entry_price: ref.entry_price,
      sl: ref.sl,
      tp: ref.tp,
      matched_signals: matched,
    },
  }];
}

if (modification_type === 'SL_TO_BE' && priorSlToBe.length > 0) {
  return skip('SL_TO_BE_DUPLICADO');
}

// Targets segun tipo — solo se actua sobre filas en el estado que tiene
// sentido para esa accion (no se inventa una accion sobre una operacion
// que todavia no existe en ese estado en MT4).
let targets;
if (modification_type === 'CLOSE_ALL_TO_BE' || modification_type === 'SL_TO_BE'
    || modification_type === 'CLOSE_AT_PRICE' || modification_type === 'TP_UPDATE') {
  targets = matched.filter((s) => s.status === 'OPEN');
} else if (modification_type === 'CANCEL') {
  targets = matched.filter((s) => ['PENDING_CONFIRMATION', 'CONFIRMED'].includes(s.status));
} else {
  targets = [];
}

if (targets.length === 0) {
  return skip('SIN_OPERACION_APLICABLE_' + modification_type);
}

return [{
  json: {
    outcome: 'INSERT',
    modification_type,
    target_price,
    raw_text: rawText,
    message_id: original.message_id,
    targets,
  },
}];

// Fase 4: una fila de signal_modifications (y una posible accion de EA) por
// cada señal objetivo (normalmente 1, o todas las sub-señales OPEN para
// CLOSE_ALL_TO_BE). Mapeo modification_type -> accion EA, solo para las
// acciones que el EA YA soporta hoy (mt4-bridge/FORMATO_ARCHIVOS.md 4.3,
// confirmado contra dashboard/main.py VALID_POSITION_ACTIONS = SET_BE,
// SET_TP_BE, CLOSE):
//   SL_TO_BE / CLOSE_ALL_TO_BE -> SET_BE (mueve el SL al precio de apertura)
//   CLOSE_AT_PRICE             -> CLOSE  (cierra a mercado, precio real
//                                          puede diferir del target_price,
//                                          que es solo referencia/auditoria)
// CANCEL y TP_UPDATE (con target_price arbitrario) NO tienen accion de EA
// equivalente hoy — se registran en signal_modifications sin ea_action,
// ver nota en el resumen final de la tarea.
const parent = $json;

const results = [];
for (const t of parent.targets) {
  let ea_action = null;
  if ((parent.modification_type === 'SL_TO_BE' || parent.modification_type === 'CLOSE_ALL_TO_BE') && t.mt4_ticket) {
    ea_action = 'SET_BE';
  } else if (parent.modification_type === 'CLOSE_AT_PRICE' && t.mt4_ticket) {
    ea_action = 'CLOSE';
  }
  results.push({
    json: {
      signal_id: t.id,
      signal_uid: t.signal_uid,
      mt4_ticket: t.mt4_ticket,
      modification_type: parent.modification_type,
      target_price: parent.target_price,
      raw_text: parent.raw_text,
      message_id: parent.message_id,
      interpreted_by: 'REGEX',
      ea_action,
    },
  });
}
return results;

