// Normaliza la respuesta de Gemini (structured JSON via responseSchema) al
// mismo shape que produce "Expandir targets" para la rama regex, y la
// enchufa al mismo INSERT/EA-action que la rama regex.
//
// Retry ya resuelto: 'Interpretar con Gemini' tiene retryOnFail (1
// reintento inmediato, protocolo seccion 4.4) y onError=continueErrorOutput
// hacia 'Insertar modificación: Gemini falló (PENDING_MANUAL)' si falla
// tras el reintento — este Code node solo corre cuando Gemini SI respondio.
//
// Limitacion vigente: solo aplica sobre la PRIMERA sub-señal encontrada
// (matched_signals[0]) — no reparte a multiples sub-señales como
// CLOSE_ALL_TO_BE, porque los tipos que llegan por Gemini (ENTRY_CHANGE,
// SL_CHANGE, CANCEL, TP_UPDATE, CLOSE_AT_PRICE) no tienen ese requisito
// en el diseño de la tarea.

const context = $('Enrutar clasificación').item.json;
const raw = $json;

let parsed;
try {
  const text = raw.candidates[0].content.parts[0].text;
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Fase 4: no se pudo parsear la respuesta estructurada de Gemini: ' + e.message);
}

const target = context.matched_signals[0];

let ea_action = null; // ninguno de los tipos que llegan por Gemini tiene
                       // accion de EA equivalente hoy (ver notas de la tarea).

return [{
  json: {
    signal_id: target.id,
    signal_uid: target.signal_uid,
    mt4_ticket: target.mt4_ticket,
    modification_type: parsed.modification_type,
    target_price: parsed.target_price != null ? Number(parsed.target_price) : null,
    raw_text: context.raw_text,
    message_id: context.message_id,
    interpreted_by: 'AI',
    ea_action,
  },
}];

// Fix bug conocido (ver nota historica de '¿Tiene accion EA?'): 'Insertar
// modificacion (Postgres)' usa RETURNING id, asi que el item que sale de
// ahi solo tiene el campo 'id' — ea_action, mt4_ticket, signal_id,
// signal_uid, modification_type, etc. no viajan solos en $json. Se
// recuperan del nodo de origen real (Expandir targets para la rama REGEX,
// Parsear respuesta Gemini para la rama AI) usando el indice de
// pairedItem, mismo patron ya usado en el workflow 05 para el problema
// analogo de 'Borrar archivo de resultado' tras un nodo Postgres.
const expandTargets = $('Expandir targets').all();
// $('Parsear respuesta Gemini').all() tira 'hasn't been executed' si el
// mensaje se clasificó por regex (nunca pasó por Gemini) — hay que
// envolverlo en try/catch, no alcanza con el fallback '||' de más abajo
// porque ambos lados de un '||' se evalúan antes de comparar.
let geminiParsed = [];
try {
  geminiParsed = $('Parsear respuesta Gemini').all();
} catch (e) {
  geminiParsed = [];
}

return $input.all().map((item) => {
  const idx = item.pairedItem.item;
  const source = expandTargets[idx] || geminiParsed[idx];
  return {
    json: {
      ...source.json,
      id: item.json.id,
    },
  };
});

// Fase 4: arma el JSON de comando sobre posicion abierta, mismo contrato
// que ya usa el dashboard (mt4-bridge/FORMATO_ARCHIVOS.md seccion 4.3):
// mt4-bridge/orders/actions/{ticket}-{action}.json
const ticket = $json.mt4_ticket;
const action = $json.ea_action;

const payload = { ticket, action };
const buffer = Buffer.from(JSON.stringify(payload, null, 2), 'utf-8');
const binary = await this.helpers.prepareBinaryData(buffer, `${ticket}-${action}.json`, 'application/json');

return [{
  json: { ...$json, action_ticket: ticket },
  binary: { data: binary },
}];
